## 🎯 Dans cette leçon

Le monde réel est **analogique** (une température, une lumière, un son) ; le microcontrôleur est **numérique**. Deux convertisseurs font le pont :

- le **CAN** (convertisseur analogique-numérique, ADC en anglais) : une tension → un nombre ;
- le **CNA** (convertisseur numérique-analogique, DAC) : un nombre → une tension.

À la fin de cette leçon, tu sauras :

- calculer la résolution et le pas d'un convertisseur ;
- convertir un nombre lu en tension, et inversement ;
- choisir entre le CAN intégré et un ADS1115 ;
- créer une vraie tension analogique avec un MCP4725 en I2C.

blocs.code:
// Leçon 3.4 — CNA en sortie (MCP4725), CAN en entrée (A0)
#include <Adafruit_MCP4725.h>   // bibliothèque Adafruit MCP4725
Adafruit_MCP4725 cna;

void setup() {
  Serial.begin(9600);
  cna.begin(0x60);   // adresse 0x60 ou 0x62 selon le module
}

void loop() {
  for (int n = 0; n <= 4095; n += 512) {
    cna.setVoltage(n, false);              // CNA : nombre -> tension
    delay(500);
    int N = analogRead(A0);                // CAN : tension -> nombre
    float attendu = n * 5.0 / 4096;
    Serial.print(n); Serial.print(" -> attendu ");
    Serial.print(attendu, 2); Serial.print(" V, relu ");
    Serial.print(N * 5.0 / 1023, 2); Serial.println(" V");
  }
}

// Solution du mini-défi : rampe de 0 à 4095 par pas de 64 (64 marches)
#include <Adafruit_MCP4725.h>
Adafruit_MCP4725 cna;

void setup() {
  Serial.begin(9600);
  cna.begin(0x60);
}

void loop() {
  for (int n = 0; n <= 4095; n += 64) {   // 4096 / 64 = 64 marches
    cna.setVoltage(n, false);
    delay(20);
    Serial.println(analogRead(A0) * 5.0 / 1023);   // une seule valeur par ligne : idéal pour le traceur
  }
}
